#' Binary Instrument and LATE
#'
#' 
#' @param data .
#' @param outcome .
#' @param treatment .
#' @param instrument .
#' @param controls .
#' @param profile .
#' @param cluster .
#' @param vce .
#' @param small .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$shares} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$profile} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effects$asDF}
#'
#' \code{as.data.frame(results$effects)}
#'
#' @export
ivlate <- function(
    data,
    outcome,
    treatment,
    instrument,
    controls,
    profile,
    cluster,
    vce = "robust",
    small = TRUE,
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivlate requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(instrument)) instrument <- jmvcore::resolveQuo(jmvcore::enquo(instrument))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(profile)) profile <- jmvcore::resolveQuo(jmvcore::enquo(profile))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(instrument), instrument, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(profile), profile, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- ivlateOptions$new(
        outcome = outcome,
        treatment = treatment,
        instrument = instrument,
        controls = controls,
        profile = profile,
        cluster = cluster,
        vce = vce,
        small = small,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivlateClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

